css:
.resume{max-width: 210mm;
      width: 100%;
      background: #ffffff;
      color: #1a1a1a;
      box-shadow: 0 12px 30px rgba(0,0,0,0.15);
      border: 1px solid #e0e0e0;
      margin: 0 auto;
      font-size: 14px;
      line-height: 1.5;
      padding: 0;}
.resume-inner{padding: 0.7in 0.7in 0.7in 0.7in;}
.resume h1, .resume h2, .resume h3, .resume p, .resume div, .resume span, .resume li{font-weight: normal;
      color: #1a1a1a;}
.name-section{margin-bottom: 0.25in;}
.name{font-size: 38pt;
      font-weight: 700;
      letter-spacing: 1.5px;
      text-transform: uppercase;
      color: #0a0a0a;
      line-height: 1.1;
      margin-bottom: 8px;
      font-family: 'Helvetica Neue', 'Arial', '思源黑体', sans-serif;}
.title-tagline{font-size: 14pt;
      font-weight: 400;
      letter-spacing: 2px;
      text-transform: uppercase;
      color: #2c2c2c;
      margin-bottom: 16px;
      border-bottom: 2.5px solid #0a0a0a;
      padding-bottom: 14px;
      display: flex;
      justify-content: space-between;
      align-items: flex-end;}
.title-role{font-weight: 600;
      color: #000;}
.title-location{font-size: 10pt;
      letter-spacing: 1px;
      color: #3d3d3d;
      font-weight: 400;}
.contact-row{display: flex;
      flex-wrap: wrap;
      gap: 18px;
      margin-top: 6px;
      font-size: 10.5pt;
      color: #2c2c2c;
      font-weight: 400;
      letter-spacing: 0.3px;}
.contact-item{display: inline-flex;
      align-items: center;
      gap: 4px;}
.contact-icon{font-weight: 600;
      color: #000;
      font-size: 11pt;}
.section{margin-top: 0.3in;}
.section-title{font-size: 13pt;
      font-weight: 700;
      letter-spacing: 1.8px;
      text-transform: uppercase;
      color: #0a0a0a;
      border-bottom: 1.5px solid #b3b3b3;
      padding-bottom: 5px;
      margin-bottom: 14px;
      font-family: 'Helvetica Neue', 'Arial', '思源黑体', sans-serif;}
.experience-item{margin-bottom: 0.2in;}
.exp-header{display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;}
.company-name{font-weight: 700;
      font-size: 15pt;
      color: #0a0a0a;
      letter-spacing: 0.4px;}
.job-title{font-weight: 500;
      font-size: 12pt;
      color: #2c2c2c;
      margin-left: 6px;
      font-style: normal;}
.date-right{font-weight: 400;
      font-size: 10.5pt;
      color: #4a4a4a;
      letter-spacing: 0.5px;
      white-space: nowrap;}
.exp-details{margin-top: 8px;
      padding-left: 0;
      list-style: none;}
.exp-details li{font-size: 11pt;
      line-height: 1.55;
      margin-bottom: 6px;
      color: #2a2a2a;
      position: relative;
      padding-left: 16px;}
.exp-details li::before{content: "•";
      position: absolute;
      left: 0;
      font-weight: 600;
      color: #0a0a0a;}
.skills-container{display: flex;
      flex-wrap: wrap;
      gap: 10px;
      margin-top: 6px;}
.skill-tag{font-size: 10.5pt;
      font-weight: 500;
      color: #1a1a1a;
      background: transparent;
      border: 1.2px solid #2c2c2c;
      padding: 5px 14px;
      letter-spacing: 0.4px;
      text-transform: uppercase;}
.edu-item{display: flex;
      justify-content: space-between;
      margin-bottom: 6px;
      font-size: 11pt;}
.edu-degree{font-weight: 700;
      color: #0a0a0a;}
.edu-school{font-weight: 400;
      color: #2c2c2c;}
.edu-date{font-weight: 400;
      color: #4a4a4a;
      white-space: nowrap;}
.misc-row{display: flex;
      flex-wrap: wrap;
      gap: 30px;
      margin-top: 8px;}
.misc-block{font-size: 11pt;}
.misc-label{font-weight: 700;
      color: #0a0a0a;
      margin-right: 6px;}
.resume hr{border: none;
      border-top: 1px solid #c0c0c0;
      margin: 16px 0 10px;}

.resume-title{font-size:9pt;letter-spacing:0.2em;color:#4a4a4a;margin-bottom:10px}.summary{font-size:11.5pt;line-height:1.6;color:#2a2a2a;margin-bottom:4px}.misc-row .misc-block{margin-bottom:4px}
